# ── Enums ──────────────────────────────────────────────────────────────────────


class Priority(str, enum.Enum):
    NORMAL = "normal"
    HIGH = "high"


@enum.unique
class Status(str, enum.Enum):
    PENDING = "pending"
    RUNNING = "running"
    DONE = "done"


# ── Data structures ────────────────────────────────────────────────────────────


@dataclasses.dataclass(frozen=True)
class Tag:
    value: str

    def __str__(self) -> str:
        return self.value


def parse_tag(tag_str: str) -> Tag:
    match = re.match(r"^tag:(\S+)$", tag_str)
    if not match:
        raise ValueError(f"Invalid tag format {tag_str}")
    tag_name = match.group(1)
    return Tag(value=tag_name)


@dataclasses.dataclass(order=True, frozen=True)
class Task:
    """
    A task that has a priority, a name, a status, and can be tagged with strings.
    """

    id: int
    name: str = dataclasses.field(compare=False)
    priority: Priority = dataclasses.field(repr=False)
    status: Status = dataclasses.field(default=Status.PENDING)
    tags: frozenset[str] = dataclasses.field(default_factory=frozenset, compare=False)
